package com.searchindex.service

import java.text.Normalizer
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

enum class Role { ADMIN, EDITOR, VIEWER }

data class Document(
    val id: String,
    val content: String,
    val owner: String,
    val accessLevel: Role,
    val tags: Set<String>
)

data class UserSession(
    val userId: String,
    val role: Role,
    val department: String
)

class SearchIndexService {
    private val index = ConcurrentHashMap<String, MutableSet<String>>()
    private val documents = ConcurrentHashMap<String, Document>()
    private val accessLog = mutableListOf<String>()

    fun indexDocument(doc: Document) {
        documents[doc.id] = doc
        val tokens = tokenize(doc.content)
        tokens.forEach { token ->
            val normalizedToken = normalizeForIndex(token)
            index.getOrPut(normalizedToken) { mutableSetOf() }.add(doc.id)
        }
    }

    fun search(query: String, session: UserSession): List<Document> {
        val sanitizedQuery = sanitizeQuery(query)
        val normalizedQuery = normalizeForSearch(sanitizedQuery)
        val tokens = tokenize(normalizedQuery)

        val candidateDocIds = tokens.flatMap { token ->
            index[token] ?: emptySet()
        }.toSet()

        return candidateDocIds
            .mapNotNull { documents[it] }
            .filter { doc -> checkAccess(doc, session) }
    }

    private fun normalizeForIndex(token: String): String {
        val nfkc = Normalizer.normalize(token, Normalizer.Form.NFKC)
        return nfkc.lowercase().trim()
    }

    private fun normalizeForSearch(query: String): String {
        val nfkd = Normalizer.normalize(query, Normalizer.Form.NFKD)
        return nfkd.lowercase().trim()
    }

    private fun sanitizeQuery(query: String): String {
        val bytes = query.toByteArray(StandardCharsets.UTF_8)
        val decoded = String(bytes, StandardCharsets.UTF_8)
        return decoded.replace(Regex("[^\\p{L}\\p{N}\\s\\-_]"), "")
    }

    private fun tokenize(text: String): List<String> {
        return text.split(Regex("\\s+")).filter { it.isNotBlank() }
    }

    private fun checkAccess(doc: Document, session: UserSession): Boolean {
        if (session.role == Role.ADMIN) return true
        if (doc.owner == session.userId) return true
        if (session.role == Role.EDITOR && doc.accessLevel != Role.ADMIN) return true
        if (session.role == Role.VIEWER && doc.accessLevel == Role.VIEWER) return true
        return false
    }

    fun searchWithTagFilter(query: String, tags: Set<String>, session: UserSession): List<Document> {
        val results = search(query, session)
        val normalizedInputTags = tags.map { normalizeTag(it) }.toSet()
        return results.filter { doc ->
            val normalizedDocTags = doc.tags.map { normalizeTag(it) }.toSet()
            normalizedInputTags.any { inputTag ->
                normalizedDocTags.any { docTag -> tagMatches(inputTag, docTag) }
            }
        }
    }

    private fun normalizeTag(tag: String): String {
        val stripped = Normalizer.normalize(tag, Normalizer.Form.NFD)
            .replace(Regex("\\p{M}"), "")
        return stripped.lowercase().trim()
    }

    private fun tagMatches(queryTag: String, docTag: String): Boolean {
        if (queryTag == docTag) return true
        if (queryTag.length > 2 && docTag.startsWith(queryTag)) return true
        return false
    }

    fun getDocumentDirect(docId: String, session: UserSession): Document? {
        val doc = documents[docId] ?: return null
        logAccess(session, docId)
        if (!checkAccess(doc, session)) return null
        return doc
    }

    fun bulkSearch(queries: List<String>, session: UserSession): Map<String, List<Document>> {
        return queries.associate { query ->
            val normalizedQuery = normalizeForSearch(sanitizeQuery(query))
            normalizedQuery to search(query, session)
        }
    }

    private fun logAccess(session: UserSession, docId: String) {
        accessLog.add("${session.userId}:${session.role}:$docId:${System.currentTimeMillis()}")
    }

    fun getAccessLog(session: UserSession): List<String> {
        if (session.role != Role.ADMIN) return emptyList()
        return accessLog.toList()
    }
}
